"""Discrete total variation as the conserved currency of the separation."""
from __future__ import annotations
from typing import Callable


def relu(y: float) -> float:
    return y if y > 0.0 else 0.0


def tent(x: float) -> float:
    return 1.0 - abs(2.0 * x - 1.0)


def iterated_tent(k: int, x: float) -> float:
    y = x
    for _ in range(k):
        y = tent(y)
    return y


def discrete_tv(g: Callable[[float], float], k: int) -> float:
    n = 2 ** k
    nodes = [i / n for i in range(n + 1)]
    return sum(abs(g(nodes[i + 1]) - g(nodes[i])) for i in range(n))


if __name__ == "__main__":
    for k in range(8):
        tv = discrete_tv(lambda x, k=k: iterated_tent(k, x), k)
        print(f"k={k}: TV={tv:.1f}  2^k={2**k}")

"""Unbounded shallow/deep gap: for any ratio R, find the depth that exceeds it."""
from __future__ import annotations


def deep_size(k: int) -> int:
    return 2 * k


def shallow_width(k: int, eps: float, A: float) -> float:
    return (2 ** k) * (1.0 - 2.0 * eps) / A


def depth_exceeding_ratio(R: float, eps: float = 0.1, A: float = 1.0) -> int:
    k = 1
    while shallow_width(k, eps, A) <= R * deep_size(k):
        k += 1
    return k


if __name__ == "__main__":
    for R in (10.0, 1e3, 1e6, 1e9):
        k = depth_exceeding_ratio(R)
        print(f"R={R:>14,.0f}:  depth k={k:3d}  "
              f"shallow≈{shallow_width(k, 0.1, 1.0):,.0f} > {R:,.0f}x{deep_size(k)}")

